        Vector3D zero = new Vector3D(0.0, 0.0, 0.0);

        // v x 0 = 0
        Vector3D result1 = Vector3D.crossProduct(v, zero);
        assertVectorEquals(zero, result1, EPSILON);

        // 0 x v = 0
        Vector3D result2 = Vector3D.crossProduct(zero, v);
