    @Test
    public void testCrossProduct_ParallelVectors() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D v2 = new Vector3D(2.0, 4.0, 6.0); // v2 = 2 * v1
        Vector3D zero = new Vector3D(0.0, 0.0, 0.0);

        // Parallel vectors should result in zero vector
        Vector3D result = Vector3D.crossProduct(v1, v2);
        assertVectorEquals(zero, result, EPSILON);
    }







    private void assertVectorEquals(Vector3D expected, Vector3D actual, double epsilon) {
        Assert.assertEquals("X component mismatch", expected.getX(), actual.getX(), epsilon);
        Assert.assertEquals("Y component mismatch", expected.getY(), actual.getY(), epsilon);
        Assert.assertEquals("Z component mismatch", expected.getZ(), actual.getZ(), epsilon);
    }
}

